/* Edexcel IGCSE Geography past paper questions — Rural Environments (Question 2). Login-protected (served under /igcse). */
window.SBL_IGCSE_PPQ = {"topic": "Rural Environments", "img": "/igcse/geography/learn/past-papers-img/", "lessons": {"IGRU01": {"n": 1, "title": "The world’s biomes", "href": "/igcse/geography/learn/rural-environments/l01-world-biomes"}, "IGRU02": {"n": 2, "title": "What is an ecosystem? Why are ecosystems so valuable?", "href": "/igcse/geography/learn/rural-environments/l02-ecosystem-goods-and-services"}, "IGRU03": {"n": 3, "title": "Exploitation of the Amazon rainforest", "href": "/igcse/geography/learn/rural-environments/l03-amazon-rainforest"}, "IGRU04": {"n": 4, "title": "Food production and farming", "href": "/igcse/geography/learn/rural-environments/l04-food-production-and-farming"}, "IGRU05": {"n": 5, "title": "Characteristics of rural areas", "href": "/igcse/geography/learn/rural-environments/l05-characteristics-of-rural-areas"}, "IGRU06": {"n": 6, "title": "How are rural areas changing in developed countries? UK case study (1)", "href": "/igcse/geography/learn/rural-environments/l06-uk-rural-change-counter-urbanisation"}, "IGRU07": {"n": 7, "title": "How are rural areas changing in developed countries? UK case study (2)", "href": "/igcse/geography/learn/rural-environments/l07-uk-rural-change-tourism-and-isolation"}, "IGRU08": {"n": 8, "title": "Diversification of farming", "href": "/igcse/geography/learn/rural-environments/l08-diversification-of-farming"}, "IGRU09": {"n": 9, "title": "How can we make life in rural areas more sustainable?", "href": "/igcse/geography/learn/rural-environments/l09-sustainable-rural-living"}, "IGRU10": {"n": 10, "title": "How are rural areas changing in developing/emerging countries? Thailand case study (1)", "href": "/igcse/geography/learn/rural-environments/l10-thailand-rural-urban-migration"}, "IGRU11": {"n": 11, "title": "Managing rural challenges in Thailand", "href": "/igcse/geography/learn/rural-environments/l11-managing-rural-challenges-thailand"}}, "parts": [{"key": "P2-2024-2ai", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 2, "id": "2(a)(i)", "marks": 1, "text": "Identify the best definition of a biome.", "intro": "", "options": [["A", "a community of animals which are connected through a food web"], ["B", "a community of animals and plants occupying a major habitat"], ["C", "a habitat where weather conditions change all year around"], ["D", "a habitat that is affected by human activity"]], "answer": "B", "type": "mcq", "lesson": "IGRU01", "ms": "AO1 (1 mark) (1)\n\nB a community of animals and plants occupying a major habitat (1)\n\nThe answer cannot be A (refers to only animals), C or D as these are not definitions of a biome.", "sources": []}, {"key": "P2-2024-2aii", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 2, "id": "2(a)(ii)", "marks": 1, "text": "State one characteristic of a desert biome.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU01", "ms": "AO1 (1 mark) (1)\n\nAward 1 mark for suitable characteristics.\n\n• Hot (climate) (1)\n• Dry (climate) (1)\n• Low rainfall /lack of precipitation (1)\n• Little/sparse vegetation/named suitable vegetation (1)\n• Dry/sandy soils (1)\n• Low biodiversity (1)\n\nAccept any other appropriate responses.", "sources": []}, {"key": "P2-2024-2b", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 2, "id": "2(b)", "marks": 2, "text": "Study Figure 2a in the Resource Booklet. Explain one factor that can affect the distribution of biomes.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU01", "ms": "AO2 (1 mark) / AO3 (1 mark) (2)\n\nAward 1 mark for identification of factor (AO2) and a further 1 mark for extension through explanation linked to the resource (AO3), up to a maximum of 2 marks.\n\n• Temperature (1) leading to deserts being located in hot areas closer to the equator (1).\n• Latitude as this affects sunlight (1) leading to less forests at extreme latitudes (1).\n• Climate as this determine the type of ecosystem that can survive (1). Typically, colder climates away from the equator are where tundra forms (1).\n• Rainfall (1) as this can affect the level of plants of vegetation found in tropical grasslands (1).\n• Altitude (1) at higher altitude there are colder temperature so can often find tundra (1).\n\nAccept any other appropriate response.", "sources": [{"src": "p2-2024-q2-p53.jpg", "figs": ["2a"]}]}, {"key": "P2-2024-2c", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 2, "id": "2(c)", "marks": 1, "text": "Identify the best definition of arable farming.", "intro": "", "options": [["A", "farming that grows trees"], ["B", "farming that produces crops"], ["C", "farming that specialises in rearing fish"], ["D", "farming that specialises in rearing livestock"]], "answer": "B", "type": "mcq", "lesson": "IGRU04", "ms": "AO1 (1 mark) (1)\n\nB farming that produces crops (1)\n\nThe answer cannot be A, C or D as these are not definitions of arable farming. A is forestry, C is fish farming and D is livestock farming.", "sources": []}, {"key": "P2-2024-2d", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 2, "id": "2(d)", "marks": 1, "text": "State one way commercial farming can affect rural environments.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU04", "ms": "AO1 (1 mark) (1)\n\nAward 1 mark for a way provided.\n\n• Water pollution/eutrophication (1)\n• Deforestation (1)\n• Reduced biodiversity/loss of habitat (1)\n• Soil erosion/degradation (1)\n• Provision of jobs (1)\n• Loss of employment due to mechanisation (1)\n• Taking up land that could be used for housing/industry/recreation (1)\n\nAccept any other appropriate response.", "sources": []}, {"key": "P2-2024-2e", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 2, "id": "2(e)", "marks": 4, "text": "Explain two reasons accessibility is important in rural environments.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU06", "ms": "AO2 (2+2 marks) (4)\n\nAward 1 mark for identification of a suitable reason and a further expansion mark, up to a maximum of 2 marks each.\n\n• To be able to commute for work (1) to ensure a stable income (1).\n• To ensure access to healthcare (1) to maintain a good quality of life (1).\n• To be able access services (1) to reduce isolation (1).\n• Access to market (1) as most farmers need a clear route to get their products to local/domestic/international markets (1).\n• To ensure workers can reach the rural areas (1) to facilitate harvests etc (1).\n• To allow people to visit farms (1) if they have diversified to include alternative activities (1).\n• Lack of public transport (1) so need routes to access jobs in other areas (1).\n\nAccept any other appropriate response.", "sources": []}, {"key": "P2-2024-2f", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 2, "id": "2(f)", "marks": 3, "text": "Study Figure 2b in the Resource Booklet. Suggest one reason why diversification is important for farmers, using the information shown.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU08", "ms": "AO1 (1 mark) / (AO3) 2 marks (3)\n\nAward 1 mark for a reason and a further 2 marks for extension through explanation or description with references to the resource, up to a maximum of 3 marks.\n\n• Diversification has the potential to increase income (1) with activities such as tourist accommodation being worth as much as £15,000 (1) which can complement income from crops/livestock (1).\n\n• Increases options to increase income (1) farms can engage in a range of alternative activities such as providing sport and recreation facilities (1) which could provide an additional £5,000 a year (1).\n\n• To reduce costs of production (1) using other diversified activities such as crop rotation (1) which could reduce the amounts of fertilisers/resources needed (1).\n\nAccept any other appropriate response.", "sources": [{"src": "p2-2024-q2-p54.jpg", "figs": ["2b"]}]}, {"key": "P2-2024-2g", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 2, "id": "2(g)", "marks": 4, "text": "For a named developed country, explain two ways tourist pressures can affect rural areas.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU07", "ms": "AO2 (4 marks) (4)\n\nAward 1 mark for initial explanation of how tourist pressures can affect rural areas, and an additional 1 mark for development through further explanation or exemplification, up to a maximum of 2 marks for each. A range of countries and tourist pressures could be chosen. For example:\n\nUK (Lake District):\n• High numbers of tourists can cause traffic congestion (1) which can lead to reduced air quality/increased noise pollution (1).\n• High demand for tourist accommodation can put pressure on housing availability (1) making homes too expensive for local people (1).\n\nAccept any other appropriate response.\n\nDo not credit pollution on its own.", "sources": []}, {"key": "P2-2024-2h", "paper": "2024", "paperLabel": "June 2024 · Paper 2", "q": 2, "id": "2(h)", "marks": 8, "text": "Study Figure 2c in the Resource Booklet. Analyse the importance of natural ecosystems for the provision of goods. You must refer to the resource in your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU02", "ms": "AO3 (4 marks)/AO4 (4 marks)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\n\nAO3\n• Natural ecosystems provide a range of goods and services.\n• Ecosystem goods are that ecosystems provide which are used by humans while services are benefits that are important for human wellbeing.\n• Typical goods provided by ecosystems include food, fuel, water, medicinal products, timber (depending on the ecosystem).\n• Services can often be categorised into:\no Regulating services such as climate or flood regulation, or holding the soil together to reduce soil erosion (in forests).\no Cultural services: such as provision of sites for tourism, science and education as health and wellbeing.\n• In some ecosystems the range of ecosystem goods may not appear to be as broad as the range of ecosystem services.\n• Such services have a large economic value, but may be less direct. While it is easy to calculate the economic value of timber from a forest, it is more complex to calculate the value of storm protection from mangroves.\n\nAO4\n• Figure 2c shows how ecosystems provide a range of different goods and services.\n• Figure 2c show how ecosystem goods can include water supply, energy, materials and food and drink.\n• Figure 2c shows how the goods provided range from energy provision to food and drink, to building materials.\n• Figure 2c suggests there are greater range of services provided than goods.\n\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout.\nA balanced, well-developed argument that synthesises relevant understanding coherently leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "p2-2024-q2-p55.jpg", "figs": ["2c"]}]}, {"key": "P2-2023R-2ai", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 2, "id": "2(a)(i)", "marks": 1, "text": "Identify a type of goods provided by a tropical forest.", "intro": "", "options": [["A", "recycling of nutrients"], ["B", "tourism"], ["C", "timber"], ["D", "wildlife habitat"]], "answer": "C", "type": "mcq", "lesson": "IGRU02", "ms": "C timber (1) (1)\n\nThe answer cannot be A, B or D as these are all services provided by a forest rather than goods.", "sources": []}, {"key": "P2-2023R-2aii", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 2, "id": "2(a)(ii)", "marks": 1, "text": "Define the term subsistence farming.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU04", "ms": "AO1 (1 mark)\n\nAward 1 mark for a suitable definition.\n\n• When crops and animals are produced by farmers to feed their family rather than selling goods at a market. (1)\n(1)\nAccept any other appropriate responses.", "sources": []}, {"key": "P2-2023R-2b", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 2, "id": "2(b)", "marks": 1, "text": "Identify the characteristic of a tundra ecosystem.", "intro": "", "options": [["A", "temperatures below 0°C most of the year"], ["B", "no presence of permafrost"], ["C", "precipitation all year round"], ["D", "rich in nutrients"]], "answer": "A", "type": "mcq", "lesson": "IGRU01", "ms": "AO1 (1 mark)\n\nA temperatures below 0oC most of the year (1)\n(1)\nThe answer cannot be B, C or D as these are not characteristics of a tundra ecosystem.", "sources": []}, {"key": "P2-2023R-2c", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 2, "id": "2(c)", "marks": 2, "text": "Study Figure 2a in the Resource Booklet. Suggest one reason suburbanisation has lead to changes in this rural area.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU06", "ms": "AO2 (1 mark) / AO3 (1 mark)\n\nAward 1 mark for basic evidence from the image (AO3) and a further 1mark for extension through explanation (AO2), up to a maximum of 2 marks.\n\n• Green spaces can be taken up with houses (1) which might cause conflicts with existing residents (1).\n\n• New homes built (1) might cause a rise in house prices (1).\n\n• Development of buildings/houses (1) could cause damage to local wildlife (1).\n\nAccept any other appropriate responses. (2)", "sources": [{"src": "p2-2023R-q2-p57.jpg", "figs": ["2a"]}]}, {"key": "P2-2023R-2d", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 2, "id": "2(d)", "marks": 1, "text": "State one way farmers try to increase crop yields.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU04", "ms": "AO1 (1 mark)\n\nAward 1 mark for a suitable way:\n• Fertilisers (1)\n• GM crops (1)\n• High yielding varieties of crops (1)\n• Increase farm size (1)\n• Pesticides/Herbicides (1)\n\nAccept any other appropriate response.\n\n(1)", "sources": []}, {"key": "P2-2023R-2e", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 2, "id": "2(e)", "marks": 4, "text": "For a named developed country, explain two ways farm incomes can be diversified.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU08", "ms": "AO2 (2+2 marks)\n\nAward 1 mark for identification of a way farm incomes are being diversified and a further mark for development or exemplification, up to a maximum of 2 marks each.\n\nMaximum 2 marks where a developing or emerging country or no country is provided.\n\nA range of examples could be provided.\n\n• United Kingdom:\no Adding a bed and breakfast on site (1) to be able to earn money from tourism. (1).\no Changing part of the farm to pick your own (1) to attract a wider range of people to the farm.\n\n• USA:\no Allowing land to be used for wind turbines (1) to earn money for generating energy as well as (4) growing crops (1).\no Opening a farm shop (1) so produce can be sold direct to consumers rather than just through intermediaries (1).\n\nAccept any other appropriate response.", "sources": []}, {"key": "P2-2023R-2f", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 2, "id": "2(f)", "marks": 3, "text": "Study Figure 2b in the Resource Booklet. Suggest one way the patterns shown in Figure 2b might change the characteristics of rural areas.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU06", "ms": "AO1 (1 mark) / (AO3) 2 marks\n\nAward 1 mark for an identification of a pattern and a further 2 marks for extension through explanation or description, up to a maximum of 3 marks.\n\n• Most Polish cities have experienced an outflow of residents (1) which may lead to high demand for housing in suburban areas (1) which encroaches into rural areas (1).\n\n• A lot of movement to the suburbs (1) which there could be infrastructure developments (1) which could improve accessibility of some rural areas (1).\n\nAccept any other appropriate response. (3)", "sources": [{"src": "p2-2023R-q2-p58.jpg", "figs": ["2b"]}]}, {"key": "P2-2023R-2g", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 2, "id": "2(g)", "marks": 4, "text": "Explain two strategies being used to make rural living more sustainable in developing or emerging countries.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU09", "ms": "AO2 (4 marks)\n\nAward 1 mark for each strategy and an additional 1 mark for development through further explanation or exemplification.\nMaximum 2 marks for each strategy.\n\nA range of strategies chosen and countries referred to.\n\n• Efforts from NGOs to improve access to electricity (1) so people can run appliances from their home reliably (1).\n• Introducing GM crops (1) which can improve yields or be more pest resistant (1).\n• Reduce the use of pesticides and chemicals (1) and produce goods with certification standards which can gain a higher price from consumers (1).\n\nAccept any other appropriate response.\n\n(4)", "sources": []}, {"key": "P2-2023R-2h", "paper": "2023R", "paperLabel": "June 2023 · Paper 2R", "q": 2, "id": "2(h)", "marks": 8, "text": "Study Figure 2c in the Resource Booklet. Analyse the factors that are leading to changes in rural areas in developing and emerging countries. Refer to the resource in your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU10", "ms": "AO3 (4 marks)/AO4 (4 marks)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\n\nAO3\n• The factors leading to change in rural areas are predominantly human in developing an emerging country.\n• Processes of rural-urban migration mean rural areas often lose many of their economically active population, leaving rural areas underpopulated. This leaves older age groups behind in rural areas.\n• Loss of economically active populations means there may be a shortage of suitable labourers in some areas. This could lead to reduced production in agriculture for example. If the country is experiencing a decline in primary sector industries such as agriculture then those remaining working in rural areas may need to consider alternative sources of income so diversification on farms may take place - this could involve developing tourist facilities, or switching to crops which gain a higher income but require less manual labour.\n• Globalisation often support continued economic growth in cities which means that economic development tends to focus on the urban areas supporting core-periphery theory.\n\nAO4\n• Figure 2c shows changes to the population of urban and rural populations in Brazil.\n• Figure 2c how in 1950 there was a total population of just over 50 million people which were around two thirds rural.\n• Figure 2c shows how the population of Brazil in general increased substantially over the time period to around 230 million people with the majority (around 90%) of these being urban.\n• Figure 2c shows how after 2000 there was a slow decline in rural populations.\n\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "p2-2023R-q2-p59.jpg", "figs": ["2c"]}]}, {"key": "P2-2022-2ai", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 2, "id": "2(a)(i)", "marks": 1, "text": "Identify one characteristic associated with a tropical forest.", "intro": "", "options": [["A", "arid conditions"], ["B", "low temperature"], ["C", "high humidity"], ["D", "strong winds"]], "answer": "C", "type": "mcq", "lesson": "IGRU01", "ms": "C High humidity (1).\n\nThe answer cannot be A (rainforests are not arid), B (rainforests have high temperatures), or D (these are associated with tundra climate). (1)", "sources": []}, {"key": "P2-2022-2aii", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 2, "id": "2(a)(ii)", "marks": 1, "text": "Define the term biome.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU01", "ms": "AO1 (1 mark)\n\n• Plant and animal community covering a large area of the Earth’s surface (1).\n• A large ecological area defined by abiotic factors (e.g. climate/relief/vegetation) (1).\n(1)\nAccept any other appropriate responses.", "sources": []}, {"key": "P2-2022-2b", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 2, "id": "2(b)", "marks": 1, "text": "Identify the meaning of the term organic farming.", "intro": "", "options": [["A", "farming that only produces genetically modified crops."], ["B", "farming that uses chemical fertilisers."], ["C", "farming that does not require irrigation."], ["D", "farming that does not use chemical fertilisers."]], "answer": "D", "type": "mcq", "lesson": "IGRU09", "ms": "AO1 (1 mark)\n\nD Farming that does not use chemical fertilisers (1)\n(1)\nThe answer cannot be A (incorrect), B (incorrect), or C (incorrect).", "sources": []}, {"key": "P2-2022-2c", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 2, "id": "2(c)", "marks": 2, "text": "Study Figure 2a in the Resource Booklet. Suggest how this forest ecosystem might provide goods for people.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU02", "ms": "AO2 (1 mark) / AO3 (1 mark)\n\nAward 1 mark for basic evidence from the from the image (AO3) and a further 1 mark for extension through explanation (AO2), up to a maximum of 2 marks.\n\n• The machinery is cutting the trees (1) showing how the forest can provide timber (1).\n\n• There are piles of tree trunks (1) which could be used to make furniture and other goods (1).\n• The wood being collected by the loggers (1) might be used for firewood (1).\n\nAccept any other appropriate responses.\n(2)", "sources": [{"src": "p2-2022-q2-p49.jpg", "figs": ["2a"]}]}, {"key": "P2-2022-2d", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 2, "id": "2(d)", "marks": 1, "text": "State one advantage of using genetically modified (GM) crops.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU04", "ms": "AO1 (1 mark)\n\nAward 1 mark for a suitable advantage identified.\n\n• Higher yields (1).\n• More pest/disease resistant (1).\n• Greater food security (1).\n• Require less use of pesticides (1).\n• They tend to grow faster (1).\n• More tolerable to climatic conditions/more frost resistant/more drought or flood resistant (1).\n\nAccept any other appropriate response.\n(1)", "sources": []}, {"key": "P2-2022-2e", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 2, "id": "2(e)", "marks": 4, "text": "For people living in a developed country, explain two strategies used to make rural life more sustainable.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU09", "ms": "AO2 (2+2 marks)\n\nAward 1 mark for a reason and a further expansion mark, up to a maximum of 2 marks each.\n\n• Farms diversifying their income to include pick your own options and a farm shop (1) to compensate for falling prices for crops and increase profitability of the farm (1).\n• Improving transport connections to remote rural areas (1) to improve access to jobs and services.\n• Switching to organic farming (1) to try and obtain a higher price for crops produced (1).\n• Obtaining grants from the EU to establish businesses in rural areas (1) and increase community sizes (1).\n• Develop tourist attractions on farms e.g. seeing farm animals (1) in order to increase incomes (1).\n\nAccept any other appropriate response. (4)", "sources": []}, {"key": "P2-2022-2f", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 2, "id": "2(f)", "marks": 3, "text": "Study Figure 2b in the Resource Booklet. Suggest one reason for the trends shown.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU06", "ms": "AO1 (1 mark) / (AO3) 2 marks\n\nAward 1 mark for an identification of a trend and a further 2 marks for extension through explanation or description, up to a maximum of 3 marks.\n\n• There has been a decrease in the percentage of people working in agriculture between 1991-2019 (1). From around 6%-3% in France (1). This may be due to fewer people willing to work in low wage agricultural jobs (1).\n\n• There has been a decrease in the percentage of people employed in agriculture between 1991-2019 (1) but it is only a small decrease, around 0.2% for the USA (1), because the country has already shifted to more employment in other sectors (1).\n\nAccept any other appropriate response. (3)", "sources": [{"src": "p2-2022-q2-p50.jpg", "figs": ["2b"]}]}, {"key": "P2-2022-2g", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 2, "id": "2(g)", "marks": 4, "text": "Explain how governments and NGOs manage challenges in rural environments in developing or emerging countries.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU11", "ms": "AO2 (4 marks)\n\nAward 1 mark for initial explanation and an additional 1 mark for development through further explanation or exemplification. Maximum 2 marks for government strategy and maximum 2 marks for NGO strategy.\n\nA range of countries and strategies could be chosen.\n\nGovernment\n• Investment in infrastructure to improved road access to the more remote areas (1) to ensure crops can reach markets more easily (1).\n• Providing funding for irrigation schemes (1) to try and combat increasing drought conditions (1).\n\nNGOs\n• NGO, Project Chirag providing rural households with solar lighting units (1) to provide power for areas with poor access to electricity (1).\n• Water Aid provide training for local people to build toilets (1) to improve sanitation facilities (1).\n\n(4)\nAccept any other appropriate response.", "sources": []}, {"key": "P2-2022-2h", "paper": "2022", "paperLabel": "June 2022 · Paper 2", "q": 2, "id": "2(h)", "marks": 8, "text": "Study Figure 2c in the Resource Booklet. Analyse the factors that can lead to rural changes in developing or emerging countries.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU10", "ms": "AO3 (4 marks)/AO4 (4 marks)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\nFactors rural change developing countries\nAO3\n\n• There are a range of economic, social and environmental factors that are leading to change in rural areas in developing countries.\n• In many developing countries rural areas are experiencing labour shortages as people often migrate to cities to look for work with the prospect of higher wages than they could get working on farms.\n• For some rural areas environmental factors are facilitating greater change. The impacts of climate change are already affecting some areas, with increasing droughts making it more difficult to grow crops. Some farmers are trying to find alternative crops to grow in a changing climate, or for example moving to more drought resistant crops varieties.\n• There are many organisations that are trying to support changes in rural areas in developing countries. Many NGOs try to support local communities, sometimes through donation of money, equipment or expertise. Where farming methods are still very labour intensive, sometimes the shift to using technology such as tractors can support a shift to more intensive farming which can increase profits and move towards more that subsistence farming.\nAO4\n• Figure 2c indicates that NGO activity can facilitate change, sometimes through the donation of machinery which can support increasing crop yields.\n• Figure 2c suggests that there are labour supply issues as it states that many people have moved to the cities to look for work.\n• Figure 2c indicates that there are environmental issues facing farmers, with increasing drought conditions making farming more challenging.\n\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "p2-2022-q2-p51.jpg", "figs": ["2c"]}]}, {"key": "P2-2022R-2ai", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 2, "id": "2(a)(i)", "marks": 1, "text": "Identify one characteristic of the savanna biome.", "intro": "", "options": [["A", "daily rainfall"], ["B", "grassland"], ["C", "dense forest"], ["D", "permafrost"]], "answer": "B", "type": "mcq", "lesson": "IGRU01", "ms": "B Grassland\n\nThe answer cannot be A (associated with tropical rainforest), C (associated with forests), or D (associated with tundra). (1)", "sources": []}, {"key": "P2-2022R-2aii", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 2, "id": "2(a)(ii)", "marks": 1, "text": "Define the term natural ecosystem.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU02", "ms": "AO1 (1 mark)\n\n• A community of plants and animals that interact with each other and their physical environment.\n\nAccept any other appropriate responses.\n(1)", "sources": []}, {"key": "P2-2022R-2b", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 2, "id": "2(b)", "marks": 1, "text": "Identify the meaning of the term genetically-modified (GM) crops.", "intro": "", "options": [["A", "Plants with root systems that have been changed to increase size."], ["B", "Plants with DNA that have been changed to increase yield."], ["C", "Animals with DNA that have been changed to increase size."], ["D", "Livestock that have greater resistance to disease."]], "answer": "B", "type": "mcq", "lesson": "IGRU04", "ms": "AO1 (1 mark)\n\nB plants with DNA that has been changed to increase yield.\n\nThe others answers cannot be correct. A (refers to root systems), C and D (refers to animals and livestock, not crops). (1)", "sources": []}, {"key": "P2-2022R-2c", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 2, "id": "2(c)", "marks": 2, "text": "Study Figure 2a in the Resource Booklet. Suggest how this natural ecosystem might provide services.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU02", "ms": "AO2 (1 mark) / AO3 (1 mark)\n\nAward 1 mark for basic evidence from the from the image (AO3) and a further 1mark for extension through explanation (AO2), up to a maximum of 2 marks.\n\n• There appears to be a walker in the picture (1) which shows how the forest can act as a place of recreation (1).\n• The forest provides a leisure environment (1) for ecotourists (1).\n\n• The trees (1) produce oxygen (which humans need to breathe) (1).\n\n• There are wide variety of trees shown (1) indicated how the forest helps maintain biodiversity (1).\n\nAccept any other appropriate responses. (2)", "sources": [{"src": "p2-2022R-q2-p49.jpg", "figs": ["2a"]}]}, {"key": "P2-2022R-2d", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 2, "id": "2(d)", "marks": 1, "text": "State one type of land use found in a rural environment.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU05", "ms": "AO1 (1 mark)\n\nAward one mark for a suitable land use.\n\n• Agriculture (1)\n• Tourism (1)\n• Recreation/leisure (1)\n• Residential (1)\n• Mining (1)\n• Forestry (1)\n\nAccept any other appropriate response. (1)", "sources": []}, {"key": "P2-2022R-2e", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 2, "id": "2(e)", "marks": 4, "text": "Explain how NGOs have managed two challenges in rural environments in developing or emerging countries.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU11", "ms": "AO2 (2+2 marks)\n\nAward 1 mark for identification of a challenge and a further expansion mark, up to a maximum of 2 marks each.\n\n• To increase access to safe drinking water (1) NGOs such as Water Aid have helped dig wells and establish sustainable water supplies (1).\n\n• To help increase yields (1) NGOs such as Tractors for Africa have donated tractor to aid mechanisation (1).\n• To help those in rural areas have access to education (1) some NGOs such as Build Africa support education in rural communities as a route out of poverty (1). (4)\n\nAccept any other appropriate response.", "sources": []}, {"key": "P2-2022R-2f", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 2, "id": "2(f)", "marks": 3, "text": "Study Figure 2b in the Resource Booklet. Suggest one reason for the trends shown.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU10", "ms": "AO1 (1 mark) / (AO3) 2 marks\n\nAward 1 mark for an identification of a trend and a further 2 marks for extension through explanation or description, up to a maximum of 3 marks.\n\n• There has been a significant decline in the percentage of people living in rural areas in Nigeria (1) almost 20% from 1991-2019 (1) due to rapid urbanisation and associated rural-urban migration (1).\n\n• There has been a decline in the percentage of urban population in both Nigeria and China (1) although this has been slightly faster in China (1) likely to be increased industrialisation (1).\n\nAccept any other appropriate response.\n(3)", "sources": [{"src": "p2-2022R-q2-p50.jpg", "figs": ["2b"]}]}, {"key": "P2-2022R-2g", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 2, "id": "2(g)", "marks": 4, "text": "Explain one strategy used to improve health and one strategy used to improve housing in rural areas in developing or emerging countries.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU11", "ms": "AO2 (4 marks)\n\nAward 1 mark for identification of each suitable strategy for health and housing, an additional mark for development through further explanation or exemplification. Maximum two marks for each strategy.\n\nHealth:\n\n• Build a new health centre (in remote rural area) (1) to ensure rural communities can access information about healthy diets (1). Housing:\n• Improve housing to include solar powered lighting (1) to allow families to work at home in areas off the main electricity grid (1).\n(4)\nAccept any other appropriate response.", "sources": []}, {"key": "P2-2022R-2h", "paper": "2022R", "paperLabel": "June 2022 · Paper 2R", "q": 2, "id": "2(h)", "marks": 8, "text": "Study Figure 2c in the Resource Booklet. Analyse the factors that have caused rural change in developed countries.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU06", "ms": "AO3 (4 marks)/AO4 (4 marks)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\n\nAO3\n• The factors leading to change in rural areas are predominantly human.\n• Processes of rural-urban migration mean there are still labour shortages in many rural areas. Often farmers have to bring in labour especially during harvest seasons.\n• Counter-urbanisation and the desire to move away from the city is creating pressure on land in rural areas, particularly to build new housing, or new business parks/industrial estates.\n• The price of many crops has fallen, as many can be imported at a cheap price, so some farmers need to diversify their income to maintain viability, this can include pick-your-own farm, farm shops, farm experiences.\n\nAO4\n• Figure 2c shows how there are some challenges facing farmers in the United States including labour and property developers.\n• Figure 2c indicates that there are activities which can take place to try and diversify income, including opening a coffee shop.\n• Figure 2c shows how the need for labour and additional income, as well as demand for building property in rural areas may be affecting rural change in developed countries.\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "p2-2022R-q2-p51.jpg", "figs": ["2c"]}]}, {"key": "P2-2021-2ai", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 2, "id": "2(a)(i)", "marks": 1, "text": "Define the term organic farming.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU09", "ms": "AO1 (1 mark)\n\nAward 1 mark for a suitable definition.\n\n• Farming proesses that do not use artifical chemicals. (1)\n• Using organic fertilisers and pesticides to grow food. (1)\n\nAccept any other appropriate response.\n\nDo not accept farming organically.\n(1)", "sources": []}, {"key": "P2-2021-2aii", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 2, "id": "2(a)(ii)", "marks": 2, "text": "Identify two forms of farm diversification.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU08", "ms": "AO1 (2 marks)\n\nC - Creating a farm shop. (1) F - Opening a bed and breakfast for tourists. (1)\n\nA, B, D, E, are all incorrect as they focus on increasing agricultural production.\n(2)", "sources": []}, {"key": "P2-2021-2b", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 2, "id": "2(b)", "marks": 2, "text": "Study Figure 2a in the Resource Booklet. Suggest one way this dairy farm has diversified its income.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU08", "ms": "AO2 (1 mark) /AO3 (1 mark)\n\nAward 1 mark for suitable way relevant to the photograph (AO3), and a further 1 mark for extension through explanation (AO2), up to a maximum of 2 marks.\n\n• Allowing people to visit the farm to pick strawberries (1) to gain additional income not provided by cows.(1)\n• Switched to producing other crops (1) to protect against falls in the value of price of dairy products. (1)\n\nAccept any other appropriate response.\n\nEvidence must be plausibly inferred from the photograph, e.g. there are no longer cows in the photograph.\n(2)", "sources": [{"src": "p2-2021-q2-p52.jpg", "figs": ["2a"]}]}, {"key": "P2-2021-2ci", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 2, "id": "2(c)(i)", "marks": 1, "text": "State one factor leading to rural isolation.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU06", "ms": "AO1 (1 mark)\n\nAward 1 mark for a suitable factor:\n\n• Rural decline (1).\n• Shortage of workers in some rural areas (1).\n• Increased need for technology (1).\n• Closure of village services / closure of village post office / closure of local school (1).\n• Loss of bus routes (1).\n• Poor internet access (1).\n\nAccept any other appropriate response.\n(1)", "sources": []}, {"key": "P2-2021-2cii", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 2, "id": "2(c)(ii)", "marks": 4, "text": "Explain two ways tourist pressure is affecting rural areas.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU07", "ms": "AO2 (2 +2 marks)\n\nAward 1 mark for each suitable way tourists are affecting rural areas, with a further mark for explanation, up to maximum of 2 marks for each.\n\n• Increased number of tourists are causing pressures on services (1) which means local peoples‘ lives are affected. (1)\n• In national parks footpaths are being damaged (1) which means increased costs for maintenance. (1)\n• Increased traffic in small villages (1) causing congestion.\n(1)\n• Litter being left by tourists (1) damaging the natural beauty. (1)\n\nAccept any other appropriate response.\n(4)", "sources": []}, {"key": "P2-2021-2di", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 2, "id": "2(d)(i)", "marks": 1, "text": "Study Figure 2b below. Label the box with an X to indicate the year with the largest urban population.", "intro": "", "options": [], "answer": null, "type": "draw", "lesson": "IGRU10", "ms": "AO3 (1 mark)\n\nAward 1 mark for an X in the box above the 2017 column (1).\n\nX\n\n(1)", "sources": [{"src": "p2-2021-q2-fig2b.jpg", "figs": ["2b"]}]}, {"key": "P2-2021-2dii", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 2, "id": "2(d)(ii)", "marks": 1, "text": "Identify the year in which the urban population first becomes larger than the rural population.", "intro": "", "options": [["A", "1985"], ["B", "1995"], ["C", "2005"], ["D", "2017"]], "answer": "B", "type": "mcq", "lesson": "IGRU10", "ms": "AO3 (1 mark)\nB 1995 (1)\n\nA is incorrect because the rural area is larger than urban. C and\nD are incorrect because there is an earlier year where the urban population is larger than rural.\n(1)", "sources": []}, {"key": "P2-2021-2diii", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 2, "id": "2(d)(iii)", "marks": 1, "text": "State one factor leading to rural-urban migration.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU10", "ms": "AO2 (1 mark)\n\nAward 1 mark for a suitable factor.\n\n• Lack of employment. (1)\n• Rural decline/isolation. (1)\n• Better jobs in the city. (1)\n• Lack of access to education. (1)\n• Lack of transport (1).\n\nAccept any other appropriate response.\n(1)", "sources": []}, {"key": "P2-2021-2e", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 2, "id": "2(e)", "marks": 4, "text": "For a named developing or emerging country explain two environmental challenges facing rural areas.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU10", "ms": "AO2 (4 marks)\n\nAward 1 mark for each initial explanation of an environmental challenge facing rural areas and an additional mark for development through further explanation or exemplification.\nMaximum of 2 marks when no named developing/emerging country is provided.\n\nA range of countries could be used.\n\n• [Kenya]:\no Increasing frequency of droughts (1) has led to reduced food supplies. (1)\no Environmental degradation (1) due to poverty. (1)\n• [China]:\no Rural areas have been damaged by natural disasters such as floods and earthquakes (1) and often emergency aid for rural areas is limited as priority is given to urban areas (1).\no Salination of water supplies due to over irrigation (1) is reducing rice yields (1).\n\nAccept any other appropriate response.\n(4)", "sources": []}, {"key": "P2-2021-2f", "paper": "2021", "paperLabel": "Summer 2021 · Paper 2", "q": 2, "id": "2(f)", "marks": 8, "text": "Study Figure 2c in the Resource Booklet. Analyse the importance of natural ecosystems for providing goods and services.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU02", "ms": "AO3 (4 marks)/AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include the following.\n\nAO3\n• Natural ecosystems provide a wide variety of goods and services which can provide significant economic benefit to a country.\n• Goods from natural ecosystems that may be discussed include:\ntimber for building; fuelwood; food (for humans and animals); ingredients for medicine; and water.\n• For many developing and emerging countries these goods provide an important proportion of the economies’ income, fuelling the development process.\n• While the economic benefit of goods from natural ecosystems (such as natural rubber) are more easily measured, the services it provides are less easy to measure but could be argued are more important.\n• Natural ecosystem services that may be discussed include: removal of air pollutants; emission of oxygen; recycling of nutrients; recycling water; maintaing biodiversity. Some services can even provide a more direct economic benefit such as leisure opportunities through tourism.\nAO4\n• Figure 2c shows the gradual increase in natural rubber production over time from forests in Indonesia.\n• Figure 2c shows how the export value of natural rubber has varied but with an overall decrease since 2008.\n• Figure 2c shows how despite increases in production the value of goods from natural ecosystems, in this case natural rubber, can vary, quite significantly from year to year.\n• Figure 2c shows a significant drop in the export value of natural rubber after 2011.\n• Figure 2c indicates that the export value of natural rubber is not constant despite increases in production.\n\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "p2-2021-q2-p53.jpg", "figs": ["2c"]}]}, {"key": "P2-2019-2a", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 2, "id": "2(a)", "marks": 1, "text": "Identify the meaning of the term NGO.", "intro": "", "options": [["A", "non-governmental organisation"], ["B", "non-global organisation"], ["C", "non-geographically organised"], ["D", "non-global operation"]], "answer": "A", "type": "mcq", "lesson": "IGRU11", "ms": "AO1 (1 mark)\n\nA Non-Governmental Organisation (1)\n\nA is the correct answer as the other options do not have the correct meanings of the term.", "sources": []}, {"key": "P2-2019-2b", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 2, "id": "2(b)", "marks": 1, "text": "Define the term negative multiplier effect.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU06", "ms": "AO1 (1 mark)\n\n• An impact / cause / factor / trigger which causes a bad / negative income on the overall economy of an area (1). (1)\n• A problem that leads to / triggers other issues or problems occurring (1)\n• A spiral of decline that creates other issues, e.g. depopulation or lowers development and investment (1)\n• A chain of events that leads to a negative impact on the people / economy of an area (1).\n• Decline in one area creates decline in another area, e.g. negative feedback loop (1)\n\nAccept any other appropriate response.\n\nNote: Do not accept “downwards spiral of decline” or “keeps getting worse over time” just on its own.", "sources": []}, {"key": "P2-2019-2c", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 2, "id": "2(c)", "marks": 1, "text": "Identify one example of a global biome.", "intro": "", "options": [["A", "pond"], ["B", "moorland"], ["C", "salt marsh"], ["D", "tundra"]], "answer": "D", "type": "mcq", "lesson": "IGRU01", "ms": "AO1 (1 mark)\n\nD tundra\n(1)\nD is the correct answer as the other options are smaller scale ecosystems, rather than biomes.", "sources": []}, {"key": "P2-2019-2d", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 2, "id": "2(d)", "marks": 2, "text": "Study Figure 2a in the Resource Booklet. Suggest one piece of evidence from the photograph that shows this farm has diversified.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU08", "ms": "AO2 (1 mark) / AO3 (1 mark)\n\nAward 1 mark (AO3) for a reason from the image and further mark (AO2) for extension through explanation, up to a maximum of 2 marks:\n• The land-use has changed away from growing crops to one where there are lots of tourists (1) as this will likely be a more profitable use of the land (1).\n\n• Lots of visitors and families evident (1) so this is the move away from using a farm traditionally for just crops and livestock (1).\n\n• Appears that barns (background) have been converted into spaces for visitors (1) rather than their likely original (2) use as shelter for animals or storing machinery (1).\n\n• An area which is now for public use with families (1) which would not be likely in a farm which had not diversified (1).\n\nAccept any other appropriate responses.", "sources": [{"src": "p2-2019-q2-p53.jpg", "figs": ["2a"]}]}, {"key": "P2-2019-2e", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 2, "id": "2(e)", "marks": 1, "text": "State one other type of rural or farm diversification.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU08", "ms": "AO1 (1 mark)\n\nAward 1 mark for any of the following.\n\n• Bed and breakfast / B&B (1)\n\n• Camping / caravanning (1)\n\n• Vineyard (1)\n\n• Camel farming (1)\n\n• Organic farming (1)\n\n• Selling farm produce / farm shop / farm café (1) (1)\n\n• Making / selling cheese (1)\n\n• Fruit picking / PYO (1)\n\n• Farming crops as well as livestock / changing crops (1)\n\n• Energy crops / solar / wind (1)\n\nAccept any other appropriate response.\n\nNote: Reject animal farms / petting zoo as too similar to (2d).", "sources": []}, {"key": "P2-2019-2f", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 2, "id": "2(f)", "marks": 4, "text": "Explain two factors that have led to changes in rural areas in a named developed country.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU06", "ms": "AO2 (4 marks)\n\nAward 1 mark for an approach and a further expansion mark, up to a maximum of 2 marks each.\n\n• Some governments have incentivised change and particular land management (1) e.g. CAP supporting prices for some farmers (1).\n\n• Some governments and agencies have supported diversification by offering grants and set-up costs (1) this has allowed the farmer to change land practice through a financial safety-net (1).\n\n• Farmers are paid to transform their landscape (1), e.g. there are government subsidies available for managing woodland for conservation (1).\n\n• Some developers have been supported to set up new mineral extraction areas / quarries (1) which have facilitated through grants and planning restrictions (1).\n\nAccept any other appropriate response, e.g. rural-urban migration or urban-rural migration, counter urbanisation, mechanisation of farming, increasing tourism, green-belt development.\n\n(4)", "sources": []}, {"key": "P2-2019-2g", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 2, "id": "2(g)", "marks": 3, "text": "Study Figure 2b in the Resource Booklet. Suggest one reason for the trend shown.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU04", "ms": "AO1 (1 mark) / (AO3) 2 marks\n\nAward 1 mark for an identification of a reason and a further 2 marks for extension through explanation or description, up to a maximum of 3 marks.\n\n• There is an increase in the amount of grain produced 100m tonnes (1949) to 621m tonnes (2015) (1) as farms have become more mechanised (1). They use machines efficiently to produce greater yields (1)\n\n• There is an increase in the amount of grain produced 100m tonnes (1949) to 621m tonnes (2015) (1) as farms have become larger (1) and therefore there is more land in agricultural production (1).\n\nAccept any other appropriate response, which may include ideas (3) around population increase and globalisation.", "sources": [{"src": "p2-2019-q2-p54.jpg", "figs": ["2b"]}]}, {"key": "P2-2019-2h", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 2, "id": "2(h)", "marks": 4, "text": "For a named developing or emerging country, explain how two different groups or organisations have managed challenges within rural environments.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU11", "ms": "AO2 (4 marks)\n\nAward 1 mark for initial explanation and an additional 1 mark for development through further explanation or exemplification.\nMaximum of 2 marks when no named developing country is used in context, or a developed country is used instead.\n\nA range of countries and groups / organisations could be chosen, based on either increasing production, switching to using “greener” approaches, or reducing demand, e.g. with policies and incentives.\n\n• In the Vietnam Programme 133 the government has provided credit to farmers (1) and this is linked to local investment in infrastructure to help reduce poverty (1).\n\n• In Vietnam, NGOs have worked with the government also to provide better rural health and education services (1) which has lifted some people out of poverty (1).\n\n• UNICEF helps children in Africa have a better quality of life (1) by providing food and shelter to some communities (1). (4)\n\nAccept any other appropriate response.\nNote: group or organisation can be implicit or explicit.", "sources": []}, {"key": "P2-2019-2i", "paper": "2019", "paperLabel": "June 2019 · Paper 2", "q": 2, "id": "2(i)", "marks": 8, "text": "Study Figure 2c in the Resource Booklet. Analyse how exploiting natural ecosystems can affect their goods and services.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU03", "ms": "AO3 (4 marks)/AO4 (4 marks)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\n\nAO3\n• The goods and services they provide are vital to sustaining well-being, and to future economic and social development.\n• All goods and services are important, but their significance will vary both spatially and temporally, depending on a range of factors.\n• There is a complex relationship between soils, climate and vegetation which affect this overall pattern of goods and services provided by a given biome or ecosystem; for example biomes with ample rainfall and warm temperatures may have high productivity and a larger amount of provisioning\n• The pattern of biomes can be interrupted locally by people, e.g. agricultural systems which can modify the vegetation, although this map (Figure 2c) is unable to directly show these local scale effects. This can result is modification of goods and services.\n\nAO4\n• Figure 2c shows the that there are 4 types of goods and services:\nregulating, cultural, supporting and provisioning\n• On Figure 2c, it can be seen that there is no hierarchy of goods and services; all are positioned equally within the triangle\n• Figure 2c shows that each of the main goods and services contains a number of sub-ideas and linked systems related to the overarching function.\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout.\nA balanced, well-developed argument that synthesises relevant understanding coherently leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "p2-2019-q2-p55.jpg", "figs": ["2c"]}]}, {"key": "P2-2019R-2a", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 2, "id": "2(a)", "marks": 1, "text": "Identify the meaning of the term suburbanisation.", "intro": "", "options": [["A", "the outward growth of urban development"], ["B", "population movement from rural to urban areas"], ["C", "increasing movement of people from urban to rural areas"], ["D", "population movement from the suburbs to the countryside"]], "answer": "A", "type": "mcq", "lesson": "IGRU06", "ms": "AO1 (1 mark)\n\nA the outward growth of urban development (1)\n\nA is the correct answer as the other options do not describe suburbanisation.", "sources": []}, {"key": "P2-2019R-2b", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 2, "id": "2(b)", "marks": 1, "text": "Define the term GM crop.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU04", "ms": "AO1 (1 mark)\n\n• A genetically modified (crop).\n(1)", "sources": []}, {"key": "P2-2019R-2c", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 2, "id": "2(c)", "marks": 1, "text": "Identify one of the goods provided by natural ecosystems.", "intro": "", "options": [["A", "soil formation"], ["B", "waste decomposition"], ["C", "timber"], ["D", "aluminium"]], "answer": "C", "type": "mcq", "lesson": "IGRU02", "ms": "AO1 (1 mark)\n\nC timber\n(1)\nA is the correct answer as the other options do not include goods from natural ecosystems.", "sources": []}, {"key": "P2-2019R-2d", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 2, "id": "2(d)", "marks": 2, "text": "Study Figure 2a in the Resource Booklet. Explain one physical factor that could have influenced the choice of crop shown in the farming system on Figure 2a.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU04", "ms": "AO3 (1 mark) / AO1 (1 mark)\n\nAward 1 mark (AO3) for evidence from the image and a further mark (AO2) for extension through explanation, up to a maximum of 2 marks:\n\n• A good supply of water (rainfall or irrigation) from the mountains (1) which means the plants have high yield (1).\n\n• The climate will be relatively hot during the day in Taiwan (1) so the plants grow well increasing productivity (1).\n\n• Appears to be a flat and possibly lowland area (1) so the field can be flooded / irrigated for the crop to thrive (1).\n\n• Large area (of open space) with few buildings in the foreground (1) so they can grow a large crop of rice (1)\n(2)\nAccept any other appropriate response, e.g. able to use machinery, quality of soil, weather which can be inferred from the resource.", "sources": [{"src": "p2-2019R-q2-p49.jpg", "figs": ["2a"]}]}, {"key": "P2-2019R-2e", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 2, "id": "2(e)", "marks": 1, "text": "State one way that farmers can modify natural ecosystems to improve farm system productivity.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU04", "ms": "AO1 (1 mark)\n\nAward 1 mark for any of the following.\n\n• Add nutrients (1)\n\n• Add fertilizers (1)\n\n• Drain fields (1)\n\nAccept any other appropriate response.\n(1)", "sources": []}, {"key": "P2-2019R-2f", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 2, "id": "2(f)", "marks": 4, "text": "Explain two reasons why some farmers are moving into diversification of farming.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU08", "ms": "AO2 (2+2 marks)\n\nAward 1 mark for a reason and a further expansion mark, up to a maximum of 2 marks each.\n\n• To increase farm income (1) by switching to an alternative system then more money can be generated (1).\n\n• Diversification can add value to farm products (1) e.g. selling meat grown on the farm to local markets / people (1).\n\n• Farmers are paid to transform their landscape (1), e.g. there are government subsidies available for managing woodland for conservation (1).\n\nAccept any other appropriate response, e.g. growing different crops to maintain soil health, avoid risk from climate change etc.\n\n(4)", "sources": []}, {"key": "P2-2019R-2g", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 2, "id": "2(g)", "marks": 3, "text": "Study Figure 2b in the Resource Booklet. Suggest one reason for one of the trends shown on Figure 2b.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU10", "ms": "AO1 (1 mark) / (AO3) 2 marks\n\nAward 1 mark (AO3) for a trend from the resource and a further 2 marks (AO2) for extension through explanation, up to a maximum of 3 marks.\n\n• Decreasing employment in rural areas (1) which results in rural- urban migration (1) as people try to find better paid jobs in other sectors / the city (1).\n\n• There is a decrease in agricultural employment as people are finding different jobs (1) as alternative employment will likely pay better (1) which means the that the employee has a better overall quality of life (1).\n\n• The increase in non-agriculture employment comes as a result of changing employment structures (1) which has stimulated the growth of new jobs in industry (1) and there are also more jobs in the tertiary sector as the country develops (1).\n\n(3)\nAccept any other appropriate response, including ideas linked to urbanisation, agricultural mechanisation, changing crop types and structural employment changes.", "sources": [{"src": "p2-2019R-q2-p50.jpg", "figs": ["2b"]}]}, {"key": "P2-2019R-2h", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 2, "id": "2(h)", "marks": 4, "text": "For a named developing or emerging country, explain how two different groups have managed challenges within the rural environment.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU11", "ms": "AO2 (4 marks)\n\nAward 1 mark for initial explanation and an additional 1 mark for development through further explanation or exemplification.\nMaximum of 2 marks (1 per way) when no named developing / emerging country is used in context, or a developed country is used instead.\n\nA range of countries and challenges could be chosen, based on either increasing production, switching to using “greener” approaches, or better soil management etc, e.g. with policies and incentives.\n\n• In rural China the government have promoted the use of solar panels to generate electricity (1) this is because they are environmentally low carbon and cheaper than non-renewable energy (1).\n\n• In the Vietnam Programme 133 has provided credit to farmers (1) and this is linked to local investment in infrastructure to help reduce poverty (1).\n\n• In Vietnam the government have also paid for better rural health and education services (1) which have been aided by NGOs and have lifted some people out of poverty (1).\n\nAccept any other appropriate response, but must be rural in context.\nNote group can be implicit (i.e. through the answer) or explicit for credit. (4)\n\nNote: Country (or area within a country) must be developing or emerging for full credit.", "sources": []}, {"key": "P2-2019R-2i", "paper": "2019R", "paperLabel": "June 2019 · Paper 2R", "q": 2, "id": "2(i)", "marks": 8, "text": "Study Figure 2c in the Resource Booklet. Analyse the reasons for the distribution of the world’s biomes.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGRU01", "ms": "AO3 (4 marks)/AO4 (4 marks)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the levels-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. Relevant points may include:\nAO3\n• Biomes are large scale or global scale ecosystem units.\n• Climate is the most important factor (precipitation and temperatures) in controlling the distribution in Figure 2c\n• There is a complex relationship between soils, climate and vegetation which affect this overall distribution pattern; for example climates with seasonal rainfall may have different biomes compared to those with more year- round precipitation.\n• The pattern of biomes can be interrupted locally by people, e.g. agricultural systems which can modify the vegetation, although this map (Figure 2c) is unable to show these local scale effects.\n\nAO4\n• Figure 2c shows the overall distribution of the worlds biomes is largely controlled by latitude\n• On Figure 2c, it can be seen that there are also more local effects of altitude or continentality that disrupt the pattern of vegetation.\n• Figure 2c shows that deserts for example are common in North Africa and central Australia, whereas much of northern Russia and Canada has a large belt of tundra.\n• The large mountain ranges of the Andes, Himalayas and Rockies affect the patterns with tundra and taiga common at high altitude.\nLevel Mark Descriptor 0 No rewardable material.\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "p2-2019R-q2-p51.jpg", "figs": ["2c"]}]}]};
